SELECT i.entity_id AS from_entity_id, COALESCE(src.lot_id, '') AS from_lot_id, COALESCE(src.material_code, '') AS from_material_code, o.entity_id AS to_entity_id, COALESCE(dst.lot_id, '') AS to_lot_id, COALESCE(dst.material_code, '') AS to_material_code, a.activity_id, a.activity_type, o.quantity AS quantity, a.work_order_number, a.line_code, CAST(a.occurred_at AS VARCHAR) AS occurred_at FROM mes_tracked_activity a JOIN mes_tracked_activity_input i ON i.activity_id = a.activity_id JOIN mes_tracked_activity_output o ON o.activity_id = a.activity_id JOIN mes_tracked_entity src ON src.entity_id = i.entity_id JOIN mes_tracked_entity dst ON dst.entity_id = o.entity_id ORDER BY a.activity_id, i.entity_id, o.entity_id
